solutions.naive:
class Solution:
    def smallestDivisor(self, nums, threshold):
        def score(d):
            total = 0
            for x in nums:
                total += (x + d - 1) // d
            return total
        for d in range(1,max(nums)+1):
            if score(d) <= threshold: return d
        return max(nums)

