class Solution:
    def smallestDivisor(self, nums, threshold):
        def score(d):
            total = 0
            for x in nums:
                total += (x + d - 1) // d
            return total
        lo,hi,ans=1,max(nums),max(nums)
        while lo<=hi:
            mid=(lo+hi)//2
            if score(mid)<=threshold: ans=mid; hi=mid-1
            else: lo=mid+1
        return ans

