class Solution:
    def smallestDivisor(self, nums, threshold):
        lo=max(1,(sum(nums)+threshold-1)//threshold); hi=max(nums)
        def can(d):
            total=0
            for x in nums:
                total += (x + d - 1) // d
                if total > threshold: return False
            return True
        while lo < hi:
            mid=(lo+hi)//2
            if can(mid): hi=mid
            else: lo=mid+1
        return lo

